138	/**
139	 * Lists (or searches) knowledge insights stored in the ledger's `.knowledge/` directory.
140	 *
141	 * - When `query` is present, delegates to `KnowledgeStoreManager.searchInsights()`.
142	 * - Otherwise calls `KnowledgeStoreManager.listInsights()` with scope/category/tags filters.
143	 * - `scope` is validated via `InsightScope.safeParse()`; unrecognised values are silently
144	 *   treated as "no scope filter" rather than causing an error.
145	 * - `tags` is a comma-separated string that is split before being forwarded.
146	 * - `limit` and `offset` are coerced to non-negative integers; invalid/missing values
147	 *   are silently ignored (limit → undefined, offset → 0).
148	 */
149	export async function handleListKnowledge(
150	  ledgerRoot: string,
151	  params: KnowledgeListParams = {}
152	): Promise<Insight[]> {
153	  const manager = new KnowledgeStoreManager(ledgerRoot);
154	
155	  // Validate scope — unrecognised values fall back to undefined (no filter).
156	  const scopeResult = InsightScope.safeParse(params.scope);
157	  const scope = scopeResult.success ? scopeResult.data : undefined;
158	
159	  const category = params.category ?? undefined;
160	  const project_slug = params.project_slug ?? undefined;
161	
162	  // Split comma-separated tags; ignore empty segments.
163	  const tags =
164	    params.tags && params.tags.trim().length > 0
165	      ? params.tags
166	          .split(',')
167	          .map((t) => t.trim())
168	          .filter((t) => t.length > 0)
169	      : undefined;
170	
171	  // Coerce pagination params.
172	  const limitRaw = params.limit !== undefined ? Math.floor(Number(params.limit)) : NaN;
173	  const limit = !isNaN(limitRaw) && limitRaw > 0 ? limitRaw : undefined;
174	
175	  const offsetRaw = params.offset !== undefined ? Math.floor(Number(params.offset)) : NaN;
176	  const offset = !isNaN(offsetRaw) && offsetRaw >= 0 ? offsetRaw : 0;
177	
178	  if (params.query && params.query.trim().length > 0) {
179	    return manager.searchInsights(params.query.trim(), { scope, project_slug, category, tags, limit, offset });
180	  }
181	
182	  return manager.listInsights({ scope, category, tags, project_slug, limit, offset });
183	}
