312	  /**
313	   * Moves an insight from one store to another in a single atomic lock span,
314	   * eliminating the TOCTOU window inherent in the previous add→delete two-step pattern.
315	   *
316	   * The operation performs these steps inside a single withLock(knowledgeDir) span:
317	   *   1. Resolve the source store path(s) from sourceFilter.
318	   *   2. Find the insight by id in the source store — throws if not found.
319	   *   3. Construct the moved insight: new id (from the target store's next_id counter),
320	   *      corrected scope/project_slug, and a fresh updated_at timestamp.
321	   *   4. Validate the new insight with InsightSchema.parse(…).
322	   *   5. Write the updated target store (with the new insight appended) via atomicWriteJson.
323	   *   6. Remove the original insight from the source store and write it via atomicWriteJson.
324	   *
325	   * @param id - Numeric id of the insight to move
326	   * @param sourceFilter - Scope (and optional project_slug) of the store containing the insight
327	   * @param targetScope - Destination scope ('global' or 'project')
328	   * @param targetProjectSlug - Required when targetScope === 'project'
329	   * @returns The moved Insight with new id, corrected scope/project_slug, and updated_at
330	   * @throws Error if the insight is not found in the source store(s)
331	   * @throws Error if targetScope === 'project' and targetProjectSlug is absent
332	   * @warning Do NOT call from inside a withLock(knowledgeDir, …) callback.
333	   *   This method acquires the lock itself; a nested call would deadlock.
334	   */
335	  async moveInsight(
336	    id: number,
337	    sourceFilter: { scope: InsightScope; project_slug?: string },
338	    targetScope: InsightScope,
339	    targetProjectSlug?: string
340	  ): Promise<Insight> {
341	    if (targetScope === 'project' && !targetProjectSlug) {
342	      throw new Error('targetProjectSlug is required when targetScope is "project"');
343	    }
344	
345	    return await withLock(this.knowledgeDir(), async () => {
346	      // 1. Resolve source path(s)
347	      const sourcePaths = await this._storePathsForFilter(sourceFilter);
348	
349	      // 2. Find insight in source store
350	      let sourceStorePath: string | undefined;
351	      let sourceStore: KnowledgeStore | undefined;
352	      let sourceIdx = -1;
353	
354	      for (const storePath of sourcePaths) {
355	        const store = await this._readStore(storePath);
356	        const idx = store.insights.findIndex((i) => i.id === id);
357	        if (idx !== -1) {
358	          sourceStorePath = storePath;
359	          sourceStore = store;
360	          sourceIdx = idx;
361	          break;
362	        }
363	      }
364	
365	      if (!sourceStorePath || !sourceStore || sourceIdx === -1) {
366	        throw new Error(`Insight with id ${id} not found`);
367	      }
368	
369	      const originalInsight = sourceStore.insights[sourceIdx];
370	
371	      // 3. Resolve target store path and read it
372	      const targetStorePath =
373	        targetScope === 'global'
374	          ? this.globalStorePath()
375	          : this.projectStorePath(targetProjectSlug!);
376	
377	      const targetStore = await this._readStore(targetStorePath);
378	
379	      // 4. Construct the moved insight with new id, scope, and updated_at
380	      const newNumericId = targetStore.next_id;
381	      targetStore.next_id = newNumericId + 1;
382	      const movedAt = now(); // capture once — reused for both movedInsight.updated_at and store.last_updated
383	
384	      const movedInsight: Insight = InsightSchema.parse({
385	        ...originalInsight,
386	        id: newNumericId,
387	        scope: targetScope,
388	        project_slug: targetScope === 'global' ? undefined : targetProjectSlug,
389	        updated_at: movedAt,
390	      });
391	
392	      // 5. Append to target store and write atomically
393	      targetStore.insights.push(movedInsight);
394	      targetStore.last_updated = movedAt;
395	      const validatedTarget = KnowledgeStoreSchema.parse(targetStore);
396	      await atomicWriteJson(targetStorePath, validatedTarget);
397	
398	      // 6. Remove from source store and write atomically
399	      sourceStore.insights.splice(sourceIdx, 1);
400	      sourceStore.last_updated = now();
401	      const validatedSource = KnowledgeStoreSchema.parse(sourceStore);
402	      await atomicWriteJson(sourceStorePath, validatedSource);
403	
404	      return movedInsight;
405	    });
406	  }
